    coordinates = [
        Point(float(lon), float(lat))
        for lon, lat in zip(longitudes, latitudes)
    ]

    return gpd.GeoDataFrame(
        {'City': list(cities), 'Coordinates': coordinates},
        geometry='Coordinates'
